module tb_TopModule;
    logic       clk;
    logic       areset;
    logic [7:0] d;
    logic [7:0] q;

    TopModule uut (
        .clk(clk),
        .areset(areset),
        .d(d),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        areset = 1;
        d = 8'hA5;
        #12;
        if (q !== 8'h00) begin
            $display("SELFTEST FAIL: Reset failed, q = %h", q);
            $finish;
        end

        areset = 0;
        // Wait just 3ns (before next posedge at t=15)
        #3;
        if (q !== 8'h00) begin
            $display("SELFTEST FAIL: Released reset changed q unexpectedly, q = %h", q);
            $finish;
        end

        // Wait for posedge at t=15
        #3; // t=18 now (clk was 1 at t=15)
        #1;  // hold time
        if (q !== 8'hA5) begin
            $display("SELFTEST FAIL: Expected q = A5, got %h", q);
            $finish;
        end

        d = 8'h3C;
        #10; // next posedge
        #1;  
        if (q !== 8'h3C) begin
            $display("SELFTEST FAIL: Expected q = 3C, got %h", q);
            $finish;
        end

        // Test asynchronous reset during operation
        areset = 1;
        #2;
        if (q !== 8'h00) begin
            $display("SELFTEST FAIL: Async reset failed during operation, q = %h", q);
            $finish;
        end
        areset = 0;

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
